const std = @import("std");
const GPUCoordinator = @import("distributed/gpu_coordinator.zig").GPUCoordinator;
const DistributedTrainerFuthark = @import("distributed/distributed_trainer_futhark.zig").DistributedTrainerFuthark;
const nccl = @import("distributed/nccl_bindings.zig");

const GPUVariant = enum {
    B200,
    B300,
};

const RuntimeGPUInfo = struct {
    variant: GPUVariant,
    num_gpus: usize,
    detected_gpu_label: []const u8,
};

const TrainingConfig = struct {
    num_gpus: usize,
    model_dim: usize,
    num_layers: usize,
    local_batch_size: usize,
    num_epochs: usize,
    requested_modal_gpu: []const u8,
    compatible_modal_gpu: []const u8,
    detected_gpu_label: []const u8,
    precision_label: []const u8,
};

fn detectRuntimeGPUInfo(allocator: std.mem.Allocator) !RuntimeGPUInfo {
    var detected_b300 = false;
    var detected_b200 = false;
    var gpu_count: usize = 0;

    var gpu_dir = std.fs.openDirAbsolute("/proc/driver/nvidia/gpus", .{ .iterate = true }) catch {
        return RuntimeGPUInfo{
            .variant = .B200,
            .num_gpus = 8,
            .detected_gpu_label = "NVIDIA B200",
        };
    };
    defer gpu_dir.close();

    var iterator = gpu_dir.iterate();
    while (try iterator.next()) |entry| {
        if (entry.kind != .directory) continue;
        gpu_count += 1;

        const info_path = try std.fmt.allocPrint(allocator, "/proc/driver/nvidia/gpus/{s}/information", .{entry.name});
        defer allocator.free(info_path);

        const info = std.fs.cwd().readFileAlloc(allocator, info_path, 16 * 1024) catch continue;
        defer allocator.free(info);

        if (std.mem.indexOf(u8, info, "B300") != null or std.mem.indexOf(u8, info, "GB300") != null) {
            detected_b300 = true;
        }
        if (std.mem.indexOf(u8, info, "B200") != null or std.mem.indexOf(u8, info, "GB200") != null) {
            detected_b200 = true;
        }
    }

    if (gpu_count == 0) {
        gpu_count = 8;
    }

    if (detected_b300) {
        return RuntimeGPUInfo{
            .variant = .B300,
            .num_gpus = gpu_count,
            .detected_gpu_label = "NVIDIA B300",
        };
    }

    if (detected_b200) {
        return RuntimeGPUInfo{
            .variant = .B200,
            .num_gpus = gpu_count,
            .detected_gpu_label = "NVIDIA B200",
        };
    }

    return RuntimeGPUInfo{
        .variant = .B200,
        .num_gpus = gpu_count,
        .detected_gpu_label = "NVIDIA B200",
    };
}

fn buildTrainingConfig(runtime_gpu: RuntimeGPUInfo) TrainingConfig {
    return switch (runtime_gpu.variant) {
        .B200 => TrainingConfig{
            .num_gpus = if (runtime_gpu.num_gpus == 0) 8 else runtime_gpu.num_gpus,
            .model_dim = 8192,
            .num_layers = 96,
            .local_batch_size = 64,
            .num_epochs = 10,
            .requested_modal_gpu = "B200:8",
            .compatible_modal_gpu = "B200+",
            .detected_gpu_label = runtime_gpu.detected_gpu_label,
            .precision_label = "bf16",
        },
        .B300 => TrainingConfig{
            .num_gpus = if (runtime_gpu.num_gpus == 0) 8 else runtime_gpu.num_gpus,
            .model_dim = 8192,
            .num_layers = 96,
            .local_batch_size = 64,
            .num_epochs = 10,
            .requested_modal_gpu = "B200:8",
            .compatible_modal_gpu = "B200+",
            .detected_gpu_label = runtime_gpu.detected_gpu_label,
            .precision_label = "bf16",
        },
    };
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const stdout = std.io.getStdOut().writer();

    const runtime_gpu = try detectRuntimeGPUInfo(allocator);
    const config = buildTrainingConfig(runtime_gpu);

    try stdout.writeAll("============================================================\n");
    try stdout.writeAll("JAIDE v40 GPU Training (Multi-GPU, Futhark Acceleration)\n");
    try stdout.writeAll("============================================================\n");
    try stdout.print("Modal request: {s}\n", .{config.requested_modal_gpu});
    try stdout.print("Modal compatible upgrade: {s}\n", .{config.compatible_modal_gpu});
    try stdout.print("Detected GPU: {s}\n", .{config.detected_gpu_label});
    try stdout.print("Precision: {s} (Futhark CUDA kernels)\n", .{config.precision_label});
    try stdout.print("Mode: Multi-GPU (WORLD_SIZE={d})\n", .{config.num_gpus});
    try stdout.writeAll("============================================================\n\n");

    var nccl_id: nccl.ncclUniqueId = undefined;
    const result = nccl.ncclGetUniqueId(&nccl_id);
    if (result != .ncclSuccess) {
        try stdout.writeAll("❌ Failed to generate NCCL ID\n");
        return error.NCCLGetUniqueIdFailed;
    }

    var coordinator = try GPUCoordinator.init(allocator, config.num_gpus, 0, nccl_id);
    defer coordinator.deinit();

    try stdout.print("[✅] GPU coordinator initialized ({d} GPUs)\n", .{config.num_gpus});

    var trainer = try DistributedTrainerFuthark.init(
        allocator,
        &coordinator,
        config.model_dim,
        config.local_batch_size,
    );
    defer trainer.deinit();

    try stdout.print("[✅] Futhark GPU trainer initialized (model_dim={d}, layers={d}, batch={d})\n",
        .{ config.model_dim, config.num_layers, config.local_batch_size });

    const dataset_path = "/app/arxiv_hungarian_dataset.jsonl";
    try stdout.print("\n[DATA] Loading dataset from {s}\n", .{dataset_path});

    const samples = try trainer.loadDataset(dataset_path);
    defer {
        for (samples) |sample| {
            allocator.free(sample);
        }
        allocator.free(samples);
    }

    try stdout.print("[✅] Loaded {d} training samples\n\n", .{samples.len});

    try stdout.writeAll("============================================================\n");
    try stdout.print("Starting {d}-epoch GPU training loop\n", .{config.num_epochs});
    try stdout.writeAll("============================================================\n\n");

    var epoch: usize = 0;
    while (epoch < config.num_epochs) : (epoch += 1) {
        const epoch_start = std.time.milliTimestamp();

        try stdout.print("Epoch {d}/{d}: GPU forward/backward with Futhark kernels...\n",
            .{ epoch + 1, config.num_epochs });

        const loss = try trainer.trainEpoch(samples);

        const epoch_duration = std.time.milliTimestamp() - epoch_start;
        try stdout.print("  Loss: {d:.6} | Time: {d}ms\n", .{ loss, epoch_duration });
    }

    try stdout.writeAll("\n============================================================\n");
    try stdout.writeAll("Saving checkpoints to /mnt/checkpoints/\n");
    try stdout.writeAll("============================================================\n");

    try trainer.saveCheckpoint("/mnt/checkpoints");

    try stdout.writeAll("\n[✅] GPU training completed successfully!\n");
    try stdout.writeAll("============================================================\n");
}
